export const getApiCatalogSystemPubProductsCrosssellingAccessoriesProductIdRoute = createRoute({
  method: 'get',
  path: '/api/catalog_system/pub/products/crossselling/accessories/{productId}',
  tags: ['CrossSelling'],
  summary: 'Get Product Search of Accessories',
  description: "Retrieves general information about the product's accessories.",
  operationId: 'ProductSearchAccessories',
  request: {
    headers: z.object({
      Accept: z
        .string()
        .openapi({
          param: {
            description:
              'HTTP Client Negotiation Accept Header. Indicates the types of responses the client can understand.',
            in: 'header',
            name: 'Accept',
            required: true,
            schema: { example: 'application/json', type: 'string' },
            style: 'simple',
          },
          example: 'application/json',
        }),
      'Content-Type': z
        .string()
        .openapi({
          param: {
            description: 'Describes the type of the content being sent.',
            in: 'header',
            name: 'Content-Type',
            required: true,
            schema: { example: 'application/json', type: 'string' },
            style: 'simple',
          },
          example: 'application/json',
        }),
    }),
    params: z.object({
      productId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: "Product's unique identifier",
            in: 'path',
            name: 'productId',
            required: true,
            schema: { example: 1, type: 'integer' },
          },
          example: 1,
        }),
    }),
  },
  responses: { 200: { description: 'OK' } },
  servers: [
    {
      url: 'https://entelperu.{environment}.com.br/api/catalog_system/pub/products/crossselling/accessories',
      variables: { environment: { default: 'DefaultParameterValue' } },
    },
  ],
})

